def backfill_published_at(apps, schema_editor):
    """Products already on show count as published when they were made, so
    followers are not told about the whole shelf as if it were new."""
    Product = apps.get_model("marketplace", "Product")
    for product in Product.objects.filter(status="published", published_at__isnull=True):
        Product.objects.filter(pk=product.pk).update(published_at=product.created_at)


